import java.util.Scanner;

public class Commands {
    static String handle(String raw) {
        String cmd = raw.strip();                    // use the returned string.
        if (cmd.equalsIgnoreCase("quit")) return "bye";   // content comparison.
        if (cmd.startsWith("say ")) return cmd.substring(4);
        return "unknown: " + cmd;
    }

    static String report(int lines) {
        StringBuilder sb = new StringBuilder();      // one growing buffer.
        for (int i = 1; i <= lines; i++) {
            sb.append("line ").append(i).append('\n');
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        String typed = new Scanner("  QUIT \n").nextLine();   // like real user input.
        System.out.println(typed == "quit");         // false: different objects.
        System.out.println(handle(typed));           // bye
        System.out.println(report(3));
        System.out.println("😀".length());           // 2: two UTF-16 code units.
    }
}
